//! Multimodal interoperability/extensibility research copilot (`AFA-ids-P22-F10`).
//!
//! It negotiates caller-supplied capability manifests for imaging and omics workflows while
//! preserving semantic loss and migration evidence. The copilot never invokes a tool or moves
//! research data.

use crate::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;

pub const FEATURE_ID:&str="AFA-ids-P22-F10";
pub const CONTRACT_VERSION:&str="ids-multimodal-interoperability-extensibility-research-copilot/1.0";
pub const INPUT_SCHEMA:&str="ExternalCapability2@1";
pub const OUTPUT_SCHEMA:&str="NegotiatedIntegration3@1";
pub const CONTENT_TYPE:&str="application/vnd.aurora.negotiated-integration-3+json";
pub const PRECLINICAL_BOUNDARY:&str="preclinical-research-only; no human-subject or clinical-source data; no diagnosis, treatment, triage, enrollment, or clinical decisions";

#[derive(Debug,Clone,Copy,PartialEq,Eq,Serialize,Deserialize)]#[serde(rename_all="snake_case")]pub enum CapabilityEvidenceState{Proven,Supported,Unknown,Unmeasured,Contradicted,Negative}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ExternalCapability2{pub capability_id:String,pub provider:String,pub protocol:String,pub offered_versions:Vec<String>,pub semantic_profile:String,pub modality_order:Vec<String>,pub input_digest:ContentHash,pub output_digest:ContentHash,pub provenance_digest:ContentHash,pub replay_identity:ContentHash,pub evidence_state:CapabilityEvidenceState,pub signed:bool,pub local:bool,pub aggregate_only:bool,pub omission_order:Vec<String>,pub negative_result:bool}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ExternalCapabilityRequest2{pub schema_version:String,pub request_id:String,pub capability_id:String,pub required_version:String,pub preferred_version:String,pub semantic_profile:String,pub required_modality_order:Vec<String>,pub capabilities:Vec<ExternalCapability2>,pub replay_identity:ContentHash,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub tool_approval:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct NegotiatedIntegrationArtifact3{pub artifact_id:String,pub content_type:String,pub content_hash:ContentHash,pub semantic_loss:Vec<String>,pub provenance_digests:Vec<ContentHash>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct NegotiatedIntegration3{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub capability_id:String,pub semantic_profile:String,pub disposition:String,pub candidate_order:Vec<String>,pub selected_order:Vec<String>,pub migrated_order:Vec<String>,pub approval_required_order:Vec<String>,pub incompatible_order:Vec<String>,pub blocked_order:Vec<String>,pub missing_modality_order:Vec<String>,pub omission_order:Vec<String>,pub uncertainty_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub negotiated_version:String,pub replay_identity:ContentHash,pub integration_digest:ContentHash,pub artifact:NegotiatedIntegrationArtifact3,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum InteroperabilityExtensibilityError{#[error("invalid external capability request: {0}")]Invalid(String),#[error("negotiated integration failed validation: {0}")]Output(String)}
fn nonempty(v:&str)->bool{!v.trim().is_empty()}fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}
pub fn interoperability_extensibility_copilot_manifest()->serde_json::Value{json!({"schema_version":"aurora-research-contract/1.0","capability_id":FEATURE_ID,"version":CONTRACT_VERSION,"owner_crate":"ids","consumers":["interoperability engineer","research copilot operator","multimodal study analyst"],"behavior":"negotiate versioned external imaging and omics capability manifests","value":"makes capability matching, migration loss, modality closure, and tool approval explicit","input_schema":INPUT_SCHEMA,"output_schema":OUTPUT_SCHEMA,"effects":["invoke:declared-tools","block:unsafe-release"],"permissions":["invoke:declared-tools"],"autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY})}
impl NegotiatedIntegration3{pub fn validate(&self)->Result<(),InteroperabilityExtensibilityError>{if self.schema_version!="aurora-research-contract/1.0"||self.contract_version!=CONTRACT_VERSION||self.feature_id!=FEATURE_ID||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.boundary!=PRECLINICAL_BOUNDARY||self.artifact.content_type!=CONTENT_TYPE||!self.raw_data_local||!self.aggregate_only||!nonempty(&self.request_id)||!nonempty(&self.capability_id)||!nonempty(&self.semantic_profile)||!nonempty(&self.negotiated_version)||self.candidate_order.is_empty()||self.effect_receipts.is_empty()||!["qualified","unresolved","blocked"].contains(&self.disposition.as_str()){return Err(InteroperabilityExtensibilityError::Output("integration identity, locality, versions, candidates, or effects are incomplete".into()));}for v in [&self.candidate_order,&self.selected_order,&self.migrated_order,&self.approval_required_order,&self.incompatible_order,&self.blocked_order,&self.missing_modality_order,&self.omission_order,&self.uncertainty_order,&self.negative_evidence_order,&self.effect_receipts]{if !ordered(v){return Err(InteroperabilityExtensibilityError::Output("integration ordering is not canonical".into()));}}let all=self.candidate_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.selected_order.iter().chain(&self.migrated_order).chain(&self.approval_required_order).chain(&self.incompatible_order).chain(&self.blocked_order).cloned().collect::<Vec<_>>();if all.len()!=self.candidate_order.len()||parts.len()!=all.len()||BTreeSet::from_iter(parts)!=all{return Err(InteroperabilityExtensibilityError::Output("capability states do not partition".into()));}if !digest(&self.replay_identity)||!digest(&self.integration_digest)||self.artifact.content_hash!=self.integration_digest||self.artifact.provenance_digests.iter().any(|v|!digest(v)){return Err(InteroperabilityExtensibilityError::Output("integration digest or artifact metadata is invalid".into()));}if self.effect_receipts.iter().any(|e|e!="block:unsafe-release"&&!e.starts_with("invoke:declared-tools:")){return Err(InteroperabilityExtensibilityError::Output("effect is outside tool gate".into()));}Ok(())}pub fn digest(&self)->Result<ContentHash,InteroperabilityExtensibilityError>{self.validate()?;ContentHash::of_value(&serde_json::to_value(self).map_err(|e|InteroperabilityExtensibilityError::Output(e.to_string()))?).map_err(|e|InteroperabilityExtensibilityError::Output(e.to_string()))}}
fn validate_request(q:&ExternalCapabilityRequest2)->Result<(),InteroperabilityExtensibilityError>{if q.schema_version!=INPUT_SCHEMA||!nonempty(&q.request_id)||!nonempty(&q.capability_id)||!nonempty(&q.required_version)||!nonempty(&q.preferred_version)||!nonempty(&q.semantic_profile)||q.required_modality_order.is_empty()||!ordered(&q.required_modality_order)||q.capabilities.is_empty()||!digest(&q.replay_identity)||!ordered(&q.adversarial_events)||q.boundary!=PRECLINICAL_BOUNDARY||!q.raw_data_local||!q.aggregate_only{return Err(InteroperabilityExtensibilityError::Invalid("request identity, versions, modalities, digest, locality, or boundary is invalid".into()));}let mut ids=BTreeSet::new();for c in &q.capabilities{if !nonempty(&c.capability_id)||!nonempty(&c.provider)||!nonempty(&c.protocol)||!nonempty(&c.semantic_profile)||c.offered_versions.is_empty()||c.modality_order.is_empty()||!ordered(&c.modality_order)||!digest(&c.input_digest)||!digest(&c.output_digest)||!digest(&c.provenance_digest)||!digest(&c.replay_identity)||!ordered(&c.omission_order)||!ids.insert(c.provider.clone()){return Err(InteroperabilityExtensibilityError::Invalid("capability identity, modality ordering, digests, or provider uniqueness is invalid".into()));}}Ok(())}
pub fn negotiate_interoperability(q:&ExternalCapabilityRequest2)->Result<NegotiatedIntegration3,InteroperabilityExtensibilityError>{validate_request(q)?;let mut rows=q.capabilities.clone();rows.sort_by(|a,b|a.provider.cmp(&b.provider));let ids=rows.iter().map(|c|c.provider.clone()).collect::<Vec<_>>();let mut selected=BTreeSet::new();let mut migrated=BTreeSet::new();let mut approval=BTreeSet::new();let mut incompatible=BTreeSet::new();let mut blocked=BTreeSet::new();let mut missing_modality=BTreeSet::new();let mut omission=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();let mut provenance=BTreeSet::new();for c in &rows{let id=c.provider.clone();provenance.insert(c.provenance_digest.clone());omission.extend(c.omission_order.iter().map(|v|format!("{id}:{v}")));if c.negative_result||c.evidence_state==CapabilityEvidenceState::Negative{negative.insert(format!("{id}:negative-result"));}if c.capability_id!=q.capability_id||c.semantic_profile!=q.semantic_profile||!c.local||!c.aggregate_only{blocked.insert(id.clone());omission.insert(format!("{id}:identity-or-locality-mismatch"));}else if q.required_modality_order.iter().any(|m|!c.modality_order.contains(m)){missing_modality.insert(id.clone());incompatible.insert(id.clone());omission.insert(format!("{id}:missing-modality"));}else if c.replay_identity!=q.replay_identity{approval.insert(id.clone());uncertainty.insert(format!("{id}:replay-mismatch"));}else if !matches!(c.evidence_state,CapabilityEvidenceState::Proven|CapabilityEvidenceState::Supported){approval.insert(id.clone());uncertainty.insert(format!("{id}:evidence-not-supported"));}else if c.offered_versions.contains(&q.required_version){selected.insert(id.clone());}else if c.offered_versions.contains(&q.preferred_version){migrated.insert(id.clone());omission.insert(format!("{id}:preferred-version-migrated"));}else{incompatible.insert(id.clone());uncertainty.insert(format!("{id}:version-unavailable"));}}let global=!q.policy_allowed||!q.protected_closure||!q.signed_approval||!q.tool_approval||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty();if global{blocked.extend(ids.iter().cloned());selected.clear();migrated.clear();approval.clear();incompatible.clear();omission.insert("request:governance-or-tool-approval-blocked".into());}uncertainty.extend(q.adversarial_events.iter().map(|e|format!("adversarial:{e}")));let so=selected.iter().cloned().collect::<Vec<_>>();let mo=migrated.iter().cloned().collect::<Vec<_>>();let ao=approval.iter().cloned().collect::<Vec<_>>();let io=incompatible.iter().cloned().collect::<Vec<_>>();let bo=blocked.iter().cloned().collect::<Vec<_>>();let disposition=if global||so.is_empty()&&mo.is_empty()&&ao.is_empty(){"blocked"}else if !ao.is_empty()||!io.is_empty()||!bo.is_empty()||!missing_modality.is_empty(){"unresolved"}else{"qualified"};if disposition!="qualified"{omission.insert("request:integration-closure-not-ready".into());}let mut payload=json!({"schema_version":"aurora-research-contract/1.0","contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":q.request_id,"capability_id":q.capability_id,"semantic_profile":q.semantic_profile,"disposition":disposition,"candidate_order":ids,"selected_order":so,"migrated_order":mo,"approval_required_order":ao,"incompatible_order":io,"blocked_order":bo,"missing_modality_order":missing_modality.iter().cloned().collect::<Vec<_>>(),"omission_order":omission.iter().cloned().collect::<Vec<_>>(),"uncertainty_order":uncertainty.iter().cloned().collect::<Vec<_>>(),"negative_evidence_order":negative.iter().cloned().collect::<Vec<_>>(),"negotiated_version":q.required_version,"replay_identity":q.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let rd=ContentHash::of_value(&payload).map_err(|e|InteroperabilityExtensibilityError::Output(e.to_string()))?;payload["integration_digest"]=json!(rd);payload["artifact"]=json!({"artifact_id":format!("negotiated-integration-3:{}",q.request_id),"content_type":CONTENT_TYPE,"content_hash":rd,"semantic_loss":omission.iter().cloned().collect::<Vec<_>>(),"provenance_digests":provenance.iter().cloned().collect::<Vec<_>>(),"boundary":PRECLINICAL_BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("invoke:declared-tools:{}",q.request_id)]}else{vec!["block:unsafe-release".to_string()]});let output:NegotiatedIntegration3=serde_json::from_value(payload).map_err(|e|InteroperabilityExtensibilityError::Output(e.to_string()))?;output.validate()?;Ok(output)}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn c(p:&str)->ExternalCapability2{ExternalCapability2{capability_id:"cap:img-omics".into(),provider:p.into(),protocol:"mcp".into(),offered_versions:vec!["1.0".into()],semantic_profile:"ome-ngff".into(),modality_order:vec!["imaging".into(),"omics".into()],input_digest:h("in"),output_digest:h("out"),provenance_digest:h("prov"),replay_identity:h("r"),evidence_state:CapabilityEvidenceState::Proven,signed:true,local:true,aggregate_only:true,omission_order:vec![],negative_result:false}}fn q()->ExternalCapabilityRequest2{ExternalCapabilityRequest2{schema_version:INPUT_SCHEMA.into(),request_id:"interop:req".into(),capability_id:"cap:img-omics".into(),required_version:"1.0".into(),preferred_version:"0.9".into(),semantic_profile:"ome-ngff".into(),required_modality_order:vec!["imaging".into(),"omics".into()],capabilities:vec![c("b"),c("a")],replay_identity:h("r"),policy_allowed:true,protected_closure:true,signed_approval:true,tool_approval:true,raw_data_local:true,aggregate_only:true,adversarial_events:vec![],boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn qualified(){assert_eq!(negotiate_interoperability(&q()).unwrap().disposition,"qualified")}#[test]fn missing_modality_visible(){let mut x=q();x.capabilities[0].modality_order=vec!["imaging".into()];assert!(!negotiate_interoperability(&x).unwrap().missing_modality_order.is_empty())}#[test]fn approval_blocks(){let mut x=q();x.tool_approval=false;assert_eq!(negotiate_interoperability(&x).unwrap().disposition,"blocked")} }
